// prep + local checks of the counterparty's presentation.
// The Bearer token is an SD-JWT VC presentation with key binding (dc+sd-jwt):
// <issuer-signed JWT>~<disclosure>~...~<key-binding JWT>. Checked here, from
// the token alone:
//   - the key-binding JWT is signed by the key the credential binds (cnf.jwk),
//     covers exactly what was presented (sd_hash), is addressed to this
//     connector (aud in DSP_IAM_AUDIENCE), is fresh (iat) and carries a nonce
//     not seen before (replay);
//   - every disclosure is one the issuer committed to (_sd digests);
//   - the credential is a participant credential (vct = DSP_PARTICIPANT_VCT),
//     names its participant (sub, a did:web), is within its validity period
//     and carries a status entry.
// The issuer's signature is checked next by the W-Stack crypto provider, the
// status and the holder's DID afterwards. The connector checks the key binding
// itself, whatever the services it calls also check.
// enforce is the DEFAULT (verification is mandatory); 'off' survives only as a
// documented evidence mode.
// Outputs: 1 = next check, 2 = rejection (-> event), 3 = off mode (-> return).
function dspError(code, detail) {
    return {
        statusCode: 401,
        headers: { 'Content-Type': 'application/json', 'WWW-Authenticate': 'Bearer' },
        payload: { '@context': 'https://w3id.org/dspace/2025/1/context.jsonld', '@type': 'dspace:Error', 'dspace:code': code, 'dspace:reason': [detail] }
    };
}

const enforce = (env.get('DSP_IAM_ENFORCE') || 'enforce').toLowerCase();
msg._iamMode = enforce;

const reqHeaders = (msg.req && msg.req.headers) || {};
msg._iamCorrelationId = reqHeaders['x-correlation-id'] || crypto.randomUUID();
if (msg.res && typeof msg.res.set === 'function') msg.res.set('X-Correlation-Id', msg._iamCorrelationId);

if (enforce === 'off') {
    msg.identity = null;
    msg.iamRejected = false;
    return [null, null, msg];
}

function reject(code, detail) {
    Object.assign(msg, dspError(code, detail));
    msg.identity = null;
    msg.iamRejected = true;
    return [null, msg, null];
}

const authHeader = reqHeaders.authorization || '';
const m = /^Bearer\s+(\S+)$/i.exec(authHeader.trim());
if (!m) return reject('missing_authorization', 'Authorization: Bearer <SD-JWT VC presentation> header is required');
const token = m[1];

const audiences = (env.get('DSP_IAM_AUDIENCE') || '').split(',').map((s) => s.trim()).filter(Boolean);
if (audiences.length === 0) return reject('config_missing', 'DSP_IAM_AUDIENCE not configured — fail closed');
const vct = env.get('DSP_PARTICIPANT_VCT') || '';
if (!vct) return reject('config_missing', 'DSP_PARTICIPANT_VCT not configured — fail closed');
const ttlS = Number(env.get('DSP_IAM_VP_TTL_SECONDS') || '300');
const skewS = 60;

const eq = (x, y) => typeof x === 'string' && typeof y === 'string' && x.length === y.length &&
    crypto.timingSafeEqual(Buffer.from(x), Buffer.from(y));
const b64json = (s) => { try { return JSON.parse(Buffer.from(String(s), 'base64url').toString('utf8')); } catch (e) { return null; } };
const jwtParts = (s) => {
    const p = String(s).split('.');
    if (p.length !== 3) return null;
    const h = b64json(p[0]);
    const pl = b64json(p[1]);
    return h && pl && typeof h === 'object' && typeof pl === 'object' ? { h, pl, raw: p } : null;
};
const sha256 = (s) => crypto.createHash('sha256').update(s, 'ascii').digest('base64url');

const parts = token.split('~');
if (parts.length < 2) return reject('invalid_presentation', 'not an SD-JWT VC presentation');
const kb = parts.pop();
if (!kb) return reject('invalid_presentation', 'SD-JWT presentation has no key binding');
const [ijwt, ...discs] = parts;
const ij = jwtParts(ijwt);
const kj = jwtParts(kb);
if (!ij || !kj) return reject('invalid_presentation', 'SD-JWT presentation not readable');
if (kj.h.typ !== 'kb+jwt') return reject('invalid_presentation', 'key binding JWT has the wrong type');
if ((ij.pl._sd_alg || 'sha-256') !== 'sha-256') return reject('invalid_presentation', 'SD-JWT digest algorithm not supported');
if (!eq(kj.pl.sd_hash, sha256(ijwt + '~' + discs.map((d) => d + '~').join('')))) {
    return reject('invalid_presentation', 'key binding does not cover the presented disclosures');
}

// claims: only disclosures whose digest the issuer signed
const byDigest = {};
for (const d of discs) {
    const arr = b64json(d);
    if (!Array.isArray(arr) || (arr.length !== 3 && arr.length !== 2)) return reject('invalid_presentation', 'SD-JWT disclosure not readable');
    byDigest[sha256(d)] = arr;
}
const used = new Set();
const resolve = (v) => {
    if (Array.isArray(v)) {
        const out = [];
        for (const x of v) {
            if (x && typeof x === 'object' && !Array.isArray(x) && Object.keys(x).length === 1 && typeof x['...'] === 'string') {
                const dd = byDigest[x['...']];
                if (dd && dd.length === 2) { used.add(x['...']); out.push(resolve(dd[1])); }
            } else out.push(resolve(x));
        }
        return out;
    }
    if (v && typeof v === 'object') {
        const out = {};
        for (const [k, x] of Object.entries(v)) if (k !== '_sd' && k !== '_sd_alg') out[k] = resolve(x);
        for (const dg of Array.isArray(v._sd) ? v._sd : []) {
            const dd = byDigest[dg];
            if (dd && dd.length === 3 && !['_sd', '...'].includes(dd[1])) { used.add(dg); out[dd[1]] = resolve(dd[2]); }
        }
        return out;
    }
    return v;
};
const claims = resolve(ij.pl);
if (used.size !== Object.keys(byDigest).length) return reject('invalid_presentation', 'SD-JWT disclosure not committed by the issuer');

// the key-binding JWT is signed by the bound key
const jwk = claims.cnf && claims.cnf.jwk;
if (!jwk || typeof jwk !== 'object') return reject('holder_binding_failed', 'credential binds no holder key');
const algs = { ES256: 'sha256', ES384: 'sha384', ES512: 'sha512', EdDSA: null };
try {
    const alg = kj.h.alg;
    if (!Object.prototype.hasOwnProperty.call(algs, alg)) return reject('holder_binding_failed', 'key binding algorithm not supported');
    const key = crypto.createPublicKey({ key: jwk, format: 'jwk' });
    const ok = crypto.verify(algs[alg], Buffer.from(kj.raw[0] + '.' + kj.raw[1]),
        alg === 'EdDSA' ? key : { key, dsaEncoding: 'ieee-p1363' }, Buffer.from(kj.raw[2], 'base64url'));
    if (!ok) return reject('holder_binding_failed', 'key binding not signed by the holder key');
} catch (e) {
    return reject('holder_binding_failed', 'key binding not verifiable');
}

const nowS = Math.floor(Date.now() / 1000);
const kbAud = Array.isArray(kj.pl.aud) ? kj.pl.aud : [kj.pl.aud];
if (!kbAud.some((a) => audiences.some((x) => eq(a, x)))) return reject('invalid_audience', 'presentation not addressed to this connector');
if (typeof kj.pl.iat !== 'number' || kj.pl.iat > nowS + skewS || kj.pl.iat < nowS - ttlS) {
    return reject('token_expired', 'key binding missing or outside its ' + ttlS + ' s lifetime — fail closed');
}
if (typeof kj.pl.nonce !== 'string' || kj.pl.nonce.length < 16) return reject('invalid_presentation', 'key binding nonce missing or too short');
const nonceCache = global.get('iamNonceCache') || new Map();
for (const [k, expAt] of nonceCache) { if (expAt <= Date.now()) nonceCache.delete(k); }
global.set('iamNonceCache', nonceCache);
if (nonceCache.has(kj.pl.nonce)) return reject('replay_detected', 'presentation nonce already used');
// the nonce is only SPENT once the signatures and the status pass — an
// unsigned token must not consume a real nonce (see dsp-iam-check-status-list).
msg._iamPendingNonce = kj.pl.nonce;
msg._iamNonceTtlMs = (ttlS + skewS) * 1000;

if (!eq(claims.vct, vct)) return reject('invalid_credential', 'not a participant credential (vct)');
if (typeof claims.exp === 'number' && claims.exp < nowS) return reject('token_expired', 'participant credential expired');
if (typeof claims.nbf === 'number' && claims.nbf > nowS + skewS) return reject('invalid_credential', 'participant credential not yet valid');
if (typeof claims.sub !== 'string' || !claims.sub.startsWith('did:web:')) return reject('invalid_credential', 'participant credential names no did:web participant (sub)');
if (typeof claims.iss !== 'string' || !claims.iss.startsWith('did:')) return reject('invalid_credential', 'participant credential has no issuer DID');
const sl = claims.status && claims.status.status_list;
const idx = sl && (typeof sl.idx === 'number' ? sl.idx : (/^[0-9]{1,9}$/.test(String(sl.idx)) ? Number(sl.idx) : -1));
let statusUrl = null;
try { statusUrl = sl ? new url.URL(String(sl.uri)) : null; } catch (e) { statusUrl = null; }
if (!statusUrl || statusUrl.protocol !== 'https:' || !(idx >= 0)) return reject('invalid_credential', 'participant credential has no readable status entry');

msg._iamVp = {
    token: token,
    nonce: kj.pl.nonce,
    aud: kbAud.find((a) => audiences.includes(a)),
    issuer: claims.iss,
    holderDid: claims.sub,
    holderJwk: jwk,
    claims: claims,
    status: { uri: statusUrl.href, idx: idx }
};
msg._iamVcs = [{ issuer: claims.iss }];
return [msg, null, null];

function dspError(code, detail) {
    return {
        statusCode: 401,
        headers: { 'Content-Type': 'application/json', 'WWW-Authenticate': 'Bearer' },
        payload: { '@context': 'https://w3id.org/dspace/2025/1/context.jsonld', '@type': 'dspace:Error', 'dspace:code': code, 'dspace:reason': [detail] }
    };
}

// trusted-issuer check: the VC issuers must be in the
// DSP_TRUSTED_ISSUERS allowlist — the federation issuer's DID, not a
// local list. Empty allowlist fails CLOSED.
function reject(code, detail) {
    Object.assign(msg, dspError(code, detail));
    msg.identity = null;
    msg.iamRejected = true;
    return [null, msg];
}

const allow = (env.get('DSP_TRUSTED_ISSUERS') || '').split(/[\s,]+/).filter(Boolean);
if (allow.length === 0) return reject('untrusted_issuer', 'DSP_TRUSTED_ISSUERS is empty — fail closed');
for (const vc of msg._iamVcs) {
    if (!vc.issuer || !allow.includes(vc.issuer)) {
        return reject('untrusted_issuer', 'VC issuer not in allowlist: ' + vc.issuer);
    }
}
return [msg, null];

// Ask the W-Stack crypto provider to check the presentation:
// POST /v1/presentation/verify, x-format dc+sd-jwt, the presentation in
// standard base64, with the audience and nonce the key binding carries. It
// checks the issuer's signature on the credential; the key binding itself was
// checked in dsp-iam-prep.
function dspError(code, detail) {
    return {
        statusCode: 401,
        headers: { 'Content-Type': 'application/json', 'WWW-Authenticate': 'Bearer' },
        payload: { '@context': 'https://w3id.org/dspace/2025/1/context.jsonld', '@type': 'dspace:Error', 'dspace:code': code, 'dspace:reason': [detail] }
    };
}
function reject(code, detail) {
    Object.assign(msg, dspError(code, detail));
    msg.identity = null;
    msg.iamRejected = true;
    return [null, msg];
}

const base = (env.get('OCM_CRYPTO_URL') || '').replace(/\/+$/, '');
if (!base) return reject('config_missing', 'OCM_CRYPTO_URL not set — fail closed');
msg._iamOrigPayload = msg.payload;
msg.url = base + '/v1/presentation/verify';
msg.method = 'POST';
msg.headers = { 'Content-Type': 'application/json', 'x-format': 'dc+sd-jwt' };
msg.payload = {
    presentation: Buffer.from(msg._iamVp.token, 'utf8').toString('base64'),
    aud: msg._iamVp.aud,
    nonce: msg._iamVp.nonce,
    disclosureFrame: []
};
return [msg, null];

// The crypto provider's verdict on the presentation: valid, and for the same
// credential (issuer and participant) dsp-iam-prep read. Anything else, an
// error answer included, is a rejection. Then fetch the status list.
function dspError(code, detail) {
    return {
        statusCode: 401,
        headers: { 'Content-Type': 'application/json', 'WWW-Authenticate': 'Bearer' },
        payload: { '@context': 'https://w3id.org/dspace/2025/1/context.jsonld', '@type': 'dspace:Error', 'dspace:code': code, 'dspace:reason': [detail] }
    };
}
function reject(code, detail) {
    if ('_iamOrigPayload' in msg) { msg.payload = msg._iamOrigPayload; delete msg._iamOrigPayload; }
    Object.assign(msg, dspError(code, detail));
    msg.identity = null;
    msg.iamRejected = true;
    return [null, msg];
}

const resp = msg.payload;
const code = msg.statusCode;
if ('_iamOrigPayload' in msg) { msg.payload = msg._iamOrigPayload; delete msg._iamOrigPayload; }
delete msg.statusCode;
if (code !== 200 || !resp || typeof resp !== 'object' || resp.valid !== true) {
    return reject('invalid_signature', 'crypto provider rejected the presentation');
}
const dc = resp.disclosedCredential || {};
if (dc.iss !== msg._iamVp.issuer || dc.sub !== msg._iamVp.holderDid) {
    return reject('invalid_signature', 'crypto provider verdict is for another credential');
}
msg._iamOrigPayload = msg.payload;
msg.url = msg._iamVp.status.uri;
msg.method = 'GET';
msg.headers = { accept: 'application/statuslist+jwt' };
msg.payload = '';
return [msg, null];

// Last checks, fail closed:
//   - the status list token (IETF Token Status List, statuslist+jwt) is signed
//     by a key of the credential's issuer, is the list the credential points to
//     (sub), is not expired, and the credential's entry is 0 (valid);
//   - holder: the key the credential binds is a key of the participant's own
//     DID document, so the presenter is that participant, not just a key.
// Then the identity is set and the nonce spent.
// libs: zlib. Outputs: 1 = accepted, 2 = rejection (both -> event).
function dspError(code, detail) {
    return {
        statusCode: 401,
        headers: { 'Content-Type': 'application/json', 'WWW-Authenticate': 'Bearer' },
        payload: { '@context': 'https://w3id.org/dspace/2025/1/context.jsonld', '@type': 'dspace:Error', 'dspace:code': code, 'dspace:reason': [detail] }
    };
}
function reject(code, detail) {
    Object.assign(msg, dspError(code, detail));
    msg.identity = null;
    msg.iamRejected = true;
    return [null, msg];
}

const vp = msg._iamVp;
const b64json = (s) => { try { return JSON.parse(Buffer.from(String(s), 'base64url').toString('utf8')); } catch (e) { return null; } };
const sameKey = (a, b) => a && b && ['kty', 'crv', 'x', 'y', 'n', 'e'].every((k) => a[k] === b[k]);
const methods = (doc) => (Array.isArray(doc.verificationMethod) ? doc.verificationMethod : [])
    .filter((m) => m && m.publicKeyJwk && typeof m.id === 'string')
    .map((m) => ({ id: m.id.startsWith('#') ? doc.id + m.id : m.id, jwk: m.publicKeyJwk }));
const algs = { ES256: 'sha256', ES384: 'sha384', ES512: 'sha512', EdDSA: null };

// status list token
const [h64, p64, s64] = msg._iamStatusJwt.split('.');
const sh = b64json(h64);
const sp = b64json(p64);
if (!sh || !sp || sh.typ !== 'statuslist+jwt') return reject('status_unavailable', 'credential status list not readable');
if (typeof sh.kid !== 'string' || sh.kid.split('#')[0] !== vp.issuer) return reject('status_unavailable', 'status list not signed by the credential issuer');
const vm = methods(msg._iamDids.issuer).find((m) => m.id === sh.kid);
if (!vm || !Object.prototype.hasOwnProperty.call(algs, sh.alg)) return reject('status_unavailable', 'status list signing key not found');
let sigOk = false;
try {
    const key = crypto.createPublicKey({ key: vm.jwk, format: 'jwk' });
    sigOk = crypto.verify(algs[sh.alg], Buffer.from(h64 + '.' + p64), sh.alg === 'EdDSA' ? key : { key, dsaEncoding: 'ieee-p1363' }, Buffer.from(s64, 'base64url'));
} catch (e) {
    sigOk = false;
}
if (!sigOk) return reject('status_unavailable', 'status list signature invalid');
if (sp.sub !== vp.status.uri) return reject('status_unavailable', 'status list is not the one the credential points to');
const nowS = Math.floor(Date.now() / 1000);
if (typeof sp.exp === 'number' && sp.exp < nowS) return reject('status_unavailable', 'status list expired');
const lst = sp.status_list || {};
const bits = Number(lst.bits);
let bytes = null;
try { bytes = [1, 2, 4, 8].includes(bits) && typeof lst.lst === 'string' ? zlib.inflateSync(Buffer.from(lst.lst, 'base64url')) : null; } catch (e) { bytes = null; }
if (!bytes) return reject('status_unavailable', 'credential status list not readable');
const bitPos = vp.status.idx * bits;
const byteAt = Math.floor(bitPos / 8);
if (byteAt >= bytes.length) return reject('status_unavailable', 'credential status index outside the list');
const value = (bytes[byteAt] >> (bitPos % 8)) & ((1 << bits) - 1);
if (value !== 0) return reject('credential_revoked', 'participant credential revoked or suspended');

// holder: the bound key belongs to the participant's DID
if (msg._iamDids.holder.id !== vp.holderDid || !methods(msg._iamDids.holder).some((m) => sameKey(m.jwk, vp.holderJwk))) {
    return reject('holder_binding_failed', 'the holder key is not a key of the participant DID ' + vp.holderDid);
}

msg.identity = {
    did: vp.holderDid,
    roles: Array.isArray(vp.claims.participantRoles) ? vp.claims.participantRoles.filter((r) => typeof r === 'string') : [],
    issuer: vp.issuer,
    legalName: typeof vp.claims.legalName === 'string' ? vp.claims.legalName : undefined
};
msg.iamRejected = false;
const cache = global.get('iamNonceCache') || new Map();
cache.set(vp.nonce, Date.now() + (msg._iamNonceTtlMs || 360000));
global.set('iamNonceCache', cache);
delete msg._iamStatusJwt;
delete msg._iamDids;
return [msg, null];

// every verification result is logged as a structured event WITH
// the correlation id (an operator finds a decision in the pod logs by the
// id from the X-Correlation-Id response header).
const event = {
    event: 'iam.verify',
    correlationId: msg._iamCorrelationId || null,
    at: new Date().toISOString(),
    mode: msg._iamMode || null,
    result: msg.iamRejected ? 'rejected' : 'accepted',
    code: (msg.iamRejected && msg.payload && msg.payload['dspace:code']) || null,
    did: (msg._iamVp && msg._iamVp.holderDid) || (msg.identity && msg.identity.did) || null
};
node.warn(JSON.stringify(event));
const log = global.get('iamVerifyEvents') || [];
log.push(event);
global.set('iamVerifyEvents', log);
return msg;

// Collects what the last checks need: the status list token (from the GET
// before), then the DID documents of the issuer (its key signs the status
// list) and of the participant (its keys must include the credential's holder
// key). did:web only, cached for DSP_IAM_DID_CACHE_TTL_SECONDS.
// Called again with each fetched DID document (msg._iamDidPending set).
// Outputs: 1 = fetch a DID document, 2 = all resolved, 3 = rejection.
function dspError(code, detail) {
    return {
        statusCode: 401,
        headers: { 'Content-Type': 'application/json', 'WWW-Authenticate': 'Bearer' },
        payload: { '@context': 'https://w3id.org/dspace/2025/1/context.jsonld', '@type': 'dspace:Error', 'dspace:code': code, 'dspace:reason': [detail] }
    };
}
function reject(code, detail) {
    if ('_iamOrigPayload' in msg) { msg.payload = msg._iamOrigPayload; delete msg._iamOrigPayload; }
    delete msg._iamDidPending;
    Object.assign(msg, dspError(code, detail));
    msg.identity = null;
    msg.iamRejected = true;
    return [null, null, msg];
}

const ttlMs = Number(env.get('DSP_IAM_DID_CACHE_TTL_SECONDS') || '300') * 1000;
const cache = global.get('iamDidCache') || new Map();
for (const [k, v] of cache) { if (v.expAt <= Date.now()) cache.delete(k); }

const resp = msg.payload;
const code = msg.statusCode;
delete msg.statusCode;
if (msg._iamDidPending) {
    const did = msg._iamDidPending;
    delete msg._iamDidPending;
    if (code !== 200 || !resp || typeof resp !== 'object' || resp.id !== did) return reject('invalid_credential', 'DID document not resolvable: ' + did);
    cache.set(did, { doc: resp, expAt: Date.now() + ttlMs });
} else {
    let body = resp;
    if (Buffer.isBuffer(body)) body = body.toString('utf8');
    if (code !== 200 || typeof body !== 'string' || body.trim().split('.').length !== 3) {
        return reject('status_unavailable', 'credential status list unavailable — fail closed');
    }
    msg._iamStatusJwt = body.trim();
}
global.set('iamDidCache', cache);

const didWebUrl = (did) => {
    const segs = did.slice('did:web:'.length).split(':').map(decodeURIComponent);
    if (!segs[0] || segs.some((s) => !s || s.includes('/') || s === '.' || s === '..')) return null;
    const host = segs.shift();
    return 'https://' + host + '/' + (segs.length ? segs.join('/') + '/did.json' : '.well-known/did.json');
};
for (const did of [msg._iamVp.issuer, msg._iamVp.holderDid]) {
    if (cache.has(did)) continue;
    if (!did.startsWith('did:web:')) return reject('invalid_credential', 'only did:web DIDs can be resolved: ' + did);
    const u = didWebUrl(did);
    if (!u) return reject('invalid_credential', 'malformed did:web: ' + did);
    msg._iamDidPending = did;
    msg.url = u;
    msg.method = 'GET';
    msg.headers = { accept: 'application/did+json, application/json' };
    msg.payload = '';
    return [msg, null, null];
}
if ('_iamOrigPayload' in msg) { msg.payload = msg._iamOrigPayload; delete msg._iamOrigPayload; }
msg._iamDids = { issuer: cache.get(msg._iamVp.issuer).doc, holder: cache.get(msg._iamVp.holderDid).doc };
return [null, msg, null];
